import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.qXLDknWC.js";const p=JSON.parse(`{"title":"What's New","description":"","frontmatter":{},"headers":[],"relativePath":"whats-new.md","filePath":"whats-new.md"}`),n={name:"whats-new.md"};function i(s,e,l,h,d,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="what-s-new" tabindex="-1">What&#39;s New <a class="header-anchor" href="#what-s-new" aria-label="Permalink to &quot;What&#39;s New&quot;">​</a></h1><p>Quick overview of recent updates to CharacterVault.</p><hr><h2 id="june-2026" tabindex="-1">June 2026 <a class="header-anchor" href="#june-2026" aria-label="Permalink to &quot;June 2026&quot;">​</a></h2><h3 id="customizable-section-tabs" tabindex="-1">Customizable Section Tabs <a class="header-anchor" href="#customizable-section-tabs" aria-label="Permalink to &quot;Customizable Section Tabs&quot;">​</a></h3><p>The character editor has 18 section tabs by default — more than most people need. A new <strong>Sections</strong> tab in Settings lets you hide the tabs you don&#39;t use, reorder the rest however you like, and reset to the default order at any time.</p><ul><li><strong>Show or hide</strong> — Toggle any section tab on or off with the eye icon</li><li><strong>Reorder</strong> — Move tabs up and down with arrow buttons</li><li><strong>Reset to Defaults</strong> — Restore the original layout in one click</li><li><strong>Mobile-friendly</strong> — Arrow buttons work great on touchscreens; the mobile dropdown respects your custom order and visibility</li></ul><p><a href="/CharacterVault/docs/configuration/section-layout">Learn more →</a></p><hr><h2 id="may-2026" tabindex="-1">May 2026 <a class="header-anchor" href="#may-2026" aria-label="Permalink to &quot;May 2026&quot;">​</a></h2><h3 id="ai-creation-studio" tabindex="-1">AI Creation Studio <a class="header-anchor" href="#ai-creation-studio" aria-label="Permalink to &quot;AI Creation Studio&quot;">​</a></h3><p>The new <strong>AI Creation Studio</strong> lets you generate complete character cards from scratch using AI. Describe your concept or select from curated tags, and the AI creates a name, description, first message, and example dialogue in one flow.</p><p><strong>Features:</strong></p><ul><li><strong>Write Mode</strong> — Free-form concept descriptions</li><li><strong>Tags Mode</strong> — Visual tag selection across 6 categories (Identity, Personality, Role, Genre, Tone, Appearance)</li><li><strong>Feeling Lucky</strong> — Random tag generation with visual vortex animation</li><li><strong>Live Preview</strong> — Edit generated fields in real-time</li><li><strong>Field Regeneration</strong> — Retry or regenerate individual fields</li></ul><p><a href="/CharacterVault/docs/features/ai-creation-studio">Learn more →</a></p><hr><h3 id="model-caching-in-settings" tabindex="-1">Model Caching in Settings <a class="header-anchor" href="#model-caching-in-settings" aria-label="Permalink to &quot;Model Caching in Settings&quot;">​</a></h3><p>The <strong>Character Settings</strong> panel now caches available AI models and providers, so the model list loads instantly on repeat visits. No more waiting for your model provider to respond every time you switch back.</p><p><a href="/CharacterVault/docs/configuration/ai-setup">Configure your AI provider →</a></p><hr><h3 id="response-performance-stats" tabindex="-1">Response Performance Stats <a class="header-anchor" href="#response-performance-stats" aria-label="Permalink to &quot;Response Performance Stats&quot;">​</a></h3><p>AI responses now show performance metrics when complete — look for <strong>TTFT</strong> (time to first token) and <strong>T/S</strong> (tokens per second) in the result header. Available in both the <strong>AI Assistant</strong> chat and the <strong>AI Toolbar</strong> result panel.</p><p><a href="/CharacterVault/docs/features/ai-assistant">AI Assistant →</a><br><a href="/CharacterVault/docs/features/editor">Text Editor →</a></p><hr><h3 id="mobile-copy-buttons" tabindex="-1">Mobile Copy Buttons <a class="header-anchor" href="#mobile-copy-buttons" aria-label="Permalink to &quot;Mobile Copy Buttons&quot;">​</a></h3><p>The copy button on chat messages now appears on mobile devices, so you can quickly grab AI-generated text from your phone or tablet.</p><hr><h3 id="adjusted-sampler-ranges" tabindex="-1">Adjusted Sampler Ranges <a class="header-anchor" href="#adjusted-sampler-ranges" aria-label="Permalink to &quot;Adjusted Sampler Ranges&quot;">​</a></h3><p>The character sampler parameter sliders (temperature, top-p, etc.) now have a wider and more sensible range, giving you finer control over your generations.</p><p><a href="/CharacterVault/docs/configuration/sampler-settings">Sampler Settings →</a></p><hr><h2 id="april-2026" tabindex="-1">April 2026 <a class="header-anchor" href="#april-2026" aria-label="Permalink to &quot;April 2026&quot;">​</a></h2><h3 id="lorebook-import-export" tabindex="-1">Lorebook Import &amp; Export <a class="header-anchor" href="#lorebook-import-export" aria-label="Permalink to &quot;Lorebook Import &amp; Export&quot;">​</a></h3><p>You can now import and export lorebooks independently from the <strong>Lorebook Editor</strong>.</p><ul><li><strong>Export</strong> — Save your character&#39;s lorebook as a JSON file for sharing or backup</li><li><strong>Import</strong> — Bring in lorebook data from JSON files exported by SillyTavern and other tools</li></ul><p><a href="/CharacterVault/docs/features/lorebook-editor#import--export">Learn more →</a></p><hr><h3 id="multi-line-input-in-ai-panels" tabindex="-1">Multi-line Input in AI Panels <a class="header-anchor" href="#multi-line-input-in-ai-panels" aria-label="Permalink to &quot;Multi-line Input in AI Panels&quot;">​</a></h3><p>The AI chat input and toolbar custom instructions now support multi-line text. Press <strong>Shift+Enter</strong> to insert line breaks when writing longer prompts or detailed instructions.</p><ul><li><strong>AI Assistant chat</strong> — Multi-line input for complex queries to Orion</li><li><strong>AI Toolbar</strong> — Multi-line custom instructions for text operations</li></ul><p><a href="/CharacterVault/docs/features/ai-assistant">AI Assistant →</a><br><a href="/CharacterVault/docs/features/editor">Text Editor →</a></p><hr><h3 id="smaller-improvements" tabindex="-1">Smaller Improvements <a class="header-anchor" href="#smaller-improvements" aria-label="Permalink to &quot;Smaller Improvements&quot;">​</a></h3><ul><li><strong>Lorebook editor</strong> — Empty character books are filtered out during export</li><li><strong>History modal</strong> — Prevented content flash during modal entrance</li><li><strong>Character images</strong> — Implemented content-addressed storage for deduplication</li><li><strong>Lorebook UI</strong> — Swapped name and comment fields to match SillyTavern convention</li></ul><hr><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="/CharacterVault/docs/changelog">Full Changelog</a></li><li><a href="/CharacterVault/docs/getting-started/installation">Getting Started</a></li></ul>',47)])])}const g=t(n,[["render",i]]);export{p as __pageData,g as default};
